# Surah Al-Hajj (chapter 22) — part 2: ayat 11-20 (IDs 2606-2615)
SURAH = 22

ENTRIES = {
2606: (
"اور لوگوں میں کوئی ہے جو اللہ کی عبادت ایک کنارے پر کرتا ہے — اگر اسے خیر پہنچے تو اس سے مطمئن ہو جاتا ہے — اور اگر اسے آزمائش پہنچے تو منہ کے بل لوٹ پڑتا ہے — اس نے دنیا اور آخرت دونوں گنوا دیں — یہی کھلا نقصان ہے",
"""۱۔ ایک طرف کا مومن — صرف بھلائی میں ثابت؛ مصیبت میں مکر جاتا؛ دنیا و آخرت کا خسارہ۔
۲۔ ’’وَمِنَ النَّاسِ مَن يَعْبُدُ اللَّهَ عَلَىٰ حَرْفٍ فَإِنْ أَصَابَهُ خَيْرٌ اطْمَأَنَّ بِهِ وَإِنْ أَصَابَتْهُ فِتْنَۃٌ انقَلَبَ عَلَىٰ وَجْهِهِ خَسِرَ الدُّنْيَا وَالْآخِرَۃَ ذَٰلِكَ هُوَ الْخُسْرَانُ الْمُبِينُ‘‘ — اور لوگوں میں کوئی ہے جو اللہ کی عبادت ایک کنارے پر کرتا ہے — اگر اسے خیر پہنچے تو اس سے مطمئن ہو جاتا ہے — اور اگر اسے آزمائش پہنچے تو منہ کے بل لوٹ پڑتا ہے — اس نے دنیا اور آخرت دونوں گنوا دیں — یہی کھلا نقصان ہے — یعنی اور لوگوں میں کوئی ہے جو اللہ کی عبادت ایک کنارے پر کرتا ہے پس اگر اسے خیر پہنچے تو اس سے مطمئن ہو جاتا ہے اور اگر اسے آزمائش پہنچے تو منہ کے بل لوٹ پڑتا ہے اس نے دنیا اور آخرت دونوں گنوا دیں یہی کھلا نقصان ہے۔
۳۔ عملی سبق: مصیبت اور آسودگی دونوں میں اللہ کی عبادت کرو؛ ثابت رہو۔"""
),
2607: (
"وہ اللہ کے سوا اس کی دعا کرتا ہے جو اسے نہ نقصان پہنچا سکے اور نہ فائدہ دے سکے — یہی دور کی گمراہی ہے",
"""۱۔ بتوں کی پوجا — نہ نقصان؛ نہ فائدہ؛ دور کی گمراہی۔
۲۔ ’’يَدْعُو مِن دُونِ اللَّهِ مَا لَا يَضُرُّهُ وَمَا لَا يَنفَعُهُ ذَٰلِكَ هُوَ الضَّلَالُ الْبَعِيدُ‘‘ — وہ اللہ کے سوا اس کی دعا کرتا ہے جو اسے نہ نقصان پہنچا سکے اور نہ فائدہ دے سکے — یہی دور کی گمراہی ہے — یعنی وہ اللہ کے سوا اس کی دعا کرتا ہے جو اسے نہ نقصان پہنچا سکے اور نہ فائدہ دے سکے یہی دور کی گمراہی ہے۔
۳۔ عملی سبق: اللہ کے سوا کسی سے مدد نہ مانگو؛ صرف اسی پر بھروسہ رکھو۔"""
),
2608: (
"وہ ایسی چیز کی دعا کرتا ہے جس کا نقصان اس کے فائدے سے قریب تر ہے — واہ کیا برا ساتھی ہے اور کیا برا رفیق ہے",
"""۱۔ بتوں کا نقصان — فائدے سے قریب؛ برا ساتھی؛ برا رفیق؛ گمراہی۔
۲۔ ’’يَدْعُو لَمَن ضَرُّهُ أَقْرَبُ مِن نَّفْعِهِ لَبِئْسَ الْمَوْلَىٰ وَلَبِئْسَ الْعَشِيرُ‘‘ — وہ ایسی چیز کی دعا کرتا ہے جس کا نقصان اس کے فائدے سے قریب تر ہے — واہ کیا برا ساتھی ہے اور کیا برا رفیق ہے — یعنی وہ ایسے کی دعا کرتا ہے جس کا نقصان اس کے فائدے سے قریب تر ہے واہ کیا برا مالک ہے اور کیا برا رفیق ہے۔
۳۔ عملی سبق: بتوں اور جھوٹے معبودوں کو چھوڑو؛ اللہ کے سوا کسی کی عبادت نہ کرو۔"""
),
2609: (
"بے شک اللہ ان لوگوں کو جنہوں نے ایمان لایا اور نیک عمل کئے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں — بے شک اللہ جو چاہتا ہے وہ کرتا ہے",
"""۱۔ مومن — جنت؛ نہریں؛ اللہ کا وعدہ؛ اللہ کی قدرت۔
۲۔ ’’إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ إِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ‘‘ — بے شک اللہ ان لوگوں کو جنہوں نے ایمان لایا اور نیک عمل کئے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں — بے شک اللہ جو چاہتا ہے وہ کرتا ہے — یعنی بے شک اللہ ان لوگوں کو جنہوں نے ایمان لایا اور نیک عمل کئے باغات میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں بے شک اللہ جو چاہتا ہے وہ کرتا ہے۔
۳۔ عملی سبق: ایمان لاؤ؛ نیک عمل کرو؛ اللہ کے وعدے پر یقین رکھو۔"""
),
2610: (
"جو یہ خیال کرتا ہے کہ اللہ دنیا اور آخرت میں اس کی مدد نہیں کرے گا — تو وہ آسمان تک رسی کھینچ لے پھر کاٹ دے پھر دیکھے کہ اس کی تدبیر اس کے غصے کی چیز کو مٹا سکے یا نہیں",
"""۱۔ اللہ کی مدد سے انکار — آسمان تک رسی؛ کاٹ دیں؛ فیصلے۔
۲۔ ’’مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَۃِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى السَّمَاءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُ مَا يَغِيظُ‘‘ — جو یہ خیال کرتا ہے کہ اللہ دنیا اور آخرت میں اس کی مدد نہیں کرے گا — تو وہ آسمان تک رسی کھینچ لے پھر کاٹ دے پھر دیکھے کہ اس کی تدبیر اس کے غصے کی چیز کو مٹا سکے یا نہیں — یعنی جو یہ خیال کرتا ہے کہ اللہ دنیا اور آخرت میں اس کی مدد نہیں کرے گا تو وہ آسمان تک رسی کھینچے پھر کاٹ دے پھر دیکھے کہ اس کی تدبیر اس کی غصے کی چیز کو زائل کر سکتی ہے یا نہیں۔
۳۔ عملی سبق: اللہ کی مدد پر بھروسہ رکھو؛ اس سے ناامید نہ ہو۔"""
),
2611: (
"اور اسی طرح ہم نے اسے واضح آیات کے طور پر نازل کیا — اور یہ کہ اللہ جسے چاہتا ہے ہدایت دیتا ہے",
"""۱۔ قرآن — واضح آیات؛ اللہ کی ہدایت؛ اللہ کی رضا۔
۲۔ ’’وَكَذَٰلِكَ أَنزَلْنَاهُ آيَاتٍ بَيِّنَاتٍ وَأَنَّ اللَّهَ يَهْدِي مَن يُرِيدُ‘‘ — اور اسی طرح ہم نے اسے واضح آیات کے طور پر نازل کیا — اور یہ کہ اللہ جسے چاہتا ہے ہدایت دیتا ہے — یعنی اور اسی طرح ہم نے اسے واضح آیات بنا کر نازل کیا اور یہ کہ اللہ جسے چاہتا ہے ہدایت دیتا ہے۔
۳۔ عملی سبق: اللہ کی آیات پر ایمان لاؤ؛ اس کی ہدایت کی طلب کرو۔"""
),
2612: (
"بے شک جو ایمان لائے اور جو یہود ہوئے اور صابئین اور نصاریٰ اور مجوس اور جو شرک کرتے ہیں — بے شک اللہ ان کے درمیان قیامت کے دن فیصلہ فرمائے گا — بے شک اللہ ہر چیز پر شاہد ہے",
"""۱۔ قیامت — تمام فرقے؛ اللہ کا فیصلہ؛ اللہ شاہد۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالصَّابِئِينَ وَالنَّصَارَىٰ وَالْمَجُوسَ وَالَّذِينَ أَشْرَكُوا إِنَّ اللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَامَۃِ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ‘‘ — بے شک جو ایمان لائے اور جو یہود ہوئے اور صابئین اور نصاریٰ اور مجوس اور جو شرک کرتے ہیں — بے شک اللہ ان کے درمیان قیامت کے دن فیصلہ فرمائے گا — بے شک اللہ ہر چیز پر شاہد ہے — یعنی بے شک جو ایمان لائے اور جو یہود ہوئے اور صابئین اور نصرانی اور مجوس اور جو شرک کرتے ہیں بے شک اللہ قیامت کے دن ان کے درمیان فیصلہ کرے گا بے شک اللہ ہر چیز پر شاہد ہے۔
۳۔ عملی سبق: اللہ کے فیصلے کا انتظار کرو؛ ایمان پر رہو؛ اس کے شاہد ہونے کا خوف رکھو۔"""
),
2613: (
"کیا تمہیں معلوم نہیں کہ اللہ کے لیے سجدہ کرتے ہیں جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور سورج اور چاند اور ستارے اور پہاڑ اور درخت اور جانور اور بہت سے لوگ — اور بہت سے پر عذاب لازم ہو چکا — اور جسے اللہ ذلیل کرے اسے کوئی عزت دینے والا نہیں — بے شک اللہ جو چاہتا ہے وہ کرتا ہے",
"""۱۔ اللہ کے لیے سجدہ — تمام مخلوق؛ سورج؛ چاند؛ ستارے؛ پہاڑ؛ درخت؛ جانور؛ لوگ؛ اللہ کا فیصلہ۔ (یہ آیت سجدہ کی آیت ہے)
۲۔ ’’أَلَمْ تَرَ أَنَّ اللَّهَ يَسْجُدُ لَهُ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَابُّ وَكَثِيرٌ مِّنَ النَّاسِ وَكَثِيرٌ حَقَّ عَلَيْهِ الْعَذَابُ وَمَن يُهِنِ اللَّهُ فَمَا لَهُ مِن مُّكْرِمٍ إِنَّ اللَّهَ يَفْعَلُ مَا يَشَاءُ‘‘ — کیا تمہیں معلوم نہیں کہ اللہ کے لیے سجدہ کرتے ہیں جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور سورج اور چاند اور ستارے اور پہاڑ اور درخت اور جانور اور بہت سے لوگ — اور بہت سے پر عذاب لازم ہو چکا — اور جسے اللہ ذلیل کرے اسے کوئی عزت دینے والا نہیں — بے شک اللہ جو چاہتا ہے وہ کرتا ہے — یعنی کیا تم نے نہیں دیکھا کہ اللہ کے لیے سجدہ کرتے ہیں جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور سورج اور چاند اور ستارے اور پہاڑ اور درخت اور جانور اور بہت سے لوگ اور بہت سوں پر عذاب لازم ہو چکا اور جسے اللہ ذلیل کرے اسے کوئی عزت دینے والا نہیں بے شک اللہ جو چاہتا ہے وہ کرتا ہے۔
۳۔ عملی سبق: اللہ کے سامنے سجدہ کرو؛ اس کی عظمت مانو؛ اس کی راہ پر چلو۔"""
),
2614: (
"یہ دو فریق ہیں جو اپنے رب کے بارے میں جھگڑے — پس جنہوں نے کفر کیا ان کے لیے آگ کے کپڑے کاٹے گئے — ان کے سروں پر کھولتا ہوا پانی ڈالا جائے گا",
"""۱۔ دو فریق — کفار؛ مومن؛ آگ کے کپڑے؛ کھولتا پانی؛ اللہ کا عذاب۔
۲۔ ’’هَٰذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ فَالَّذِينَ كَفَرُوا قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ الْحَمِيمُ‘‘ — یہ دو فریق ہیں جو اپنے رب کے بارے میں جھگڑے — پس جنہوں نے کفر کیا ان کے لیے آگ کے کپڑے کاٹے گئے — ان کے سروں پر کھولتا ہوا پانی ڈالا جائے گا — یعنی یہ دو فریق ہیں جو اپنے رب کے بارے میں جھگڑے پس جنہوں نے کفر کیا ان کے لیے آگ کے کپڑے کاٹے جائیں گے ان کے سروں پر کھولتا ہوا پانی ڈالا جائے گا۔
۳۔ عملی سبق: اللہ کے بارے میں جھگڑا نہ کرو؛ ایمان پر رہو؛ اس کے عذاب سے بچو۔"""
),
2615: (
"اس سے ان کے پیٹوں کی چیزیں اور کھالیں پگھلائی جائیں گی",
"""۱۔ جہنم — پیٹ اور کھالیں پگھلیں؛ اللہ کا عذاب۔
۲۔ ’’يُصْهَرُ بِهِ مَا فِي بُطُونِهِمْ وَالْجُلُودُ‘‘ —اس سے ان کے پیٹوں کی چیزیں اور کھالیں پگھلائی جائیں گی۔
۳۔ عملی سبق: جہنم کے عذاب کا خوف رکھو؛ اللہ کی ہدایت پر چلو؛ نیک بنو۔"""
),
}
